        {
          "mistake": "Single broker — no high availability",
          "level": "production",
          "fix": "Minimum 3 brokers for production with RF=3."
        },
        {
          "mistake": "Same rack for all brokers — rack failure loses all replicas",
          "level": "senior",
          "fix": "Distribute brokers across racks/availability zones."
        }
