function hasEnrichment(dayNumber, topicName) {
  const dayData = CURRICULUM_ENRICHMENT[String(dayNumber)];
  if (!dayData) return false;
  const normalizedTopic = topicName.trim().toLowerCase();
  return Object.keys(dayData).some(
    (t) => t.trim().toLowerCase() === normalizedTopic
  );
}

function getTopicEnrichment(dayNumber, topicName) {
  const dayData = CURRICULUM_ENRICHMENT[String(dayNumber)];
  if (!dayData) return null;
  const normalizedTopic = topicName.trim().toLowerCase();
  const foundKey = Object.keys(dayData).find(
    (t) => t.trim().toLowerCase() === normalizedTopic
  );
  return foundKey ? dayData[foundKey] : null;
}

module.exports = CURRICULUM_ENRICHMENT;
module.exports.hasEnrichment = hasEnrichment;
module.exports.getTopicEnrichment = getTopicEnrichment;
